// array's members: one function per member, each declared by the //kavun:member directive in its doc comment. The
// table, arrayMethods, and the member entries of docs/reference/types/array.md (alphabetical, so the order here is
// free) are generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Add the arguments at the back as whole operands: an `array` argument spreads as a run, any other value is one
// element.
//
// `x.append(a, b)` ≡ `x + a + b`.
//
// An `array` argument spreads as a run; every other value is one element. Arguments land in order —
// `x.prepend(a, b)` puts `a, b` in that order at the front. No arguments is a no-op.
//
// ```go
// [1].append(2, 3)             // => [1, 2, 3]
// [1].append([2, 3])           // => [1, 2, 3] — spreads
// [3].prepend(1, 2)            // => [1, 2, 3] — argument order preserved at the front
// [0].append(1, [2, 3], 4)     // => [0, 1, 2, 3, 4]
// ```
//
// `prepend` is O(n) — it rebuilds the array. When building front-first in a loop, accumulate with
// `append`/`push` and `reverse()` once at the end.
//
//kavun:member append pure (...xs) -> array
func arrayAppend(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return arrayTypeAppend(v, args, false)
}

// Add the arguments at the front as whole operands, in argument order; see [`append`](#append).
//
//kavun:member prepend pure (...xs) -> array
func arrayPrepend(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	items := arrayAddItems(args)
	elems := (*Array)(v.Ptr).Elements
	out := make([]Value, 0, len(items)+len(elems))
	out = append(out, items...)
	out = append(out, elems...)
	return NewArrayValue(out, false), nil
}

// Add each argument at the back as exactly **one element**, whatever its type; an array never spreads.
//
// Postcondition: `a.push(x).last() == x`.
//
// ```go
// [1].push([2, 3])             // => [1, [2, 3]] — the pair stays a pair
// [2].push_first(0, 1)         // => [0, 1, 2]
// ```
//
//kavun:member push pure (...items) -> array
func arrayPush(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	elems := (*Array)(v.Ptr).Elements
	out := make([]Value, 0, len(elems)+len(args))
	out = append(out, elems...)
	out = append(out, args...)
	return NewArrayValue(out, false), nil
}

// Add each argument at the front as exactly one element, in argument order; see [`push`](#push).
//
//kavun:member push_first pure (...items) -> array
func arrayPushFirst(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	elems := (*Array)(v.Ptr).Elements
	out := make([]Value, 0, len(args)+len(elems))
	out = append(out, args...)
	out = append(out, elems...)
	return NewArrayValue(out, false), nil
}

// Insert each argument as one element (never spread) at position `i`.
//
// `i` outside `[0, len]` raises; a negative `i` counts from the end.
//
// ```go
// [1, 4].insert(1, 2, 3)       // => [1, 2, 3, 4]
// [1, 4].insert(1, [2, 3])     // => [1, [2, 3], 4] — one element
// [1, 2].insert(-1, 9)         // => [1, 9, 2]
// [1, 2].insert(3, 9)          // Error: index_out_of_bounds: (insert) 3 out of range [0, 2]
// ```
//
//kavun:member insert pure (i, ...items) -> array
func arrayInsert(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	elems := (*Array)(v.Ptr).Elements
	at, err := readEditPos("insert", args, len(elems))
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue(slices.Insert(slices.Clone(elems), at, args[1:]...), false), nil
}

// Removes `delete_count` elements at `start`, then inserts the items there.
//
// The inserts take the add-side reading: an `array` argument **spreads** — the wrap (or `insert`) spells the
// element. `start` outside `[0, len]` raises: reading past the end is harmless (`slice` clamps), editing past it is
// not.
//
// ```go
// [1, 2, 3, 4].splice(1, 2)          // => [1, 4]
// [1, 5].splice(1, 0, [2, 3], 4)     // => [1, 2, 3, 4, 5] — inserts spread
// [1, 5].splice(1, 0, [[2, 3]])      // => [1, [2, 3], 5] — the wrap spells the element
// [1, 2].splice(5)                   // Error: index_out_of_bounds: (splice, start index) 5 out of range [0, 2]
// ```
//
//kavun:member splice pure ([start[, delete_count]]) | (start, delete_count, ...items) -> array
func arraySplice(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	elems := (*Array)(v.Ptr).Elements
	start, end, err := readSpliceRange("splice", args, len(elems))
	if err != nil {
		return Undefined, err
	}
	var items []Value
	if len(args) > 2 {
		items = arrayAddItems(args[2:])
	}
	out := make([]Value, 0, start+len(items)+len(elems)-end)
	out = append(out, elems[:start]...)
	out = append(out, items...)
	out = append(out, elems[end:]...)
	return NewArrayValue(out, false), nil
}

// Remove every match of an element, a run, a set or a predicate; with no argument, the elements of the [blank
// set](#the-blank-set).
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// `remove` and [`keep`](#keep) are duals over the same readings, and the names say which way each one goes.
//
// Element and run readings act on **every occurrence**; absence of a match is a silent no-op. With no argument
// each takes the reading its own verb implies against the [blank set](#the-blank-set) — `keep()` keeps the
// significant elements, `remove()` removes the blank ones. Two different actions that land on the same answer,
// not one operation with two names.
//
// ```go
// [1, 2, 1, 3].remove(1)                     // => [2, 3]
// [1, 2, 3, 1, 2].remove([1, 2])             // => [3] — every occurrence of the run
// [1, 2, 3, 4].remove(func(x) { return x % 2 == 0 })   // => [1, 3]
// [1, 2, 3, 4].keep(func(x) { return x % 2 == 0 })   // => [2, 4]
// [1, 2, 3, 4].remove(1, 3)                  // => [2, 4] — a set
// [1, 0, undefined, "", 0.0, [], 2].remove() // => [1, 2] — drops the blank set
// ```
//
//kavun:member remove pure (...x) -> array
func arrayRemove(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := arrayRemaining(vm, "remove", v, args)
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue(out, false), nil
}

// Keep only the matches of an element, a run, a set or a predicate; with no argument, the significant elements; see
// [`remove`](#remove).
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
//kavun:member keep pure (...x) -> array
func arrayKeep(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := arrayKept(vm, "keep", v, args)
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue(out, false), nil
}

// Report whether an element, a run, a member of a set or a predicate match occurs; with no argument, whether any
// element is significant.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// It takes all five readings: element, run, variadic set, predicate, and no-argument (any element outside the blank
// set).
//
// `contains(fn)` ≡ `any(fn)` and `contains()` ≡ `any()`.
//
// ```go
// [1, 2, 3].contains([2, 3])         // => true — a run
// [1, 2, 3].contains(range(2, 4))    // => false — a range is one element; say .array() for the run
// [0, undefined].contains()          // => false — only blanks
// [0, undefined, 1].contains()       // => true
// ```
//
//kavun:member contains pure (...x) -> bool
func arrayContains(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := arrayReadMatchArgs(vm, "contains", args, true)
	if err != nil {
		return Undefined, err
	}
	elems := (*Array)(v.Ptr).Elements

	if m.runs != nil {
		for _, r := range m.runs {
			if len(r) == 0 {
				return True, nil
			}
		}
		for i := range elems {
			if arrayRunLengthAt(elems, i, m.runs) > 0 {
				return True, nil
			}
		}
		return False, nil
	}

	for i, e := range elems {
		hit, err := m.matches(i, e)
		if err != nil {
			return Undefined, err
		}
		if hit {
			return True, nil
		}
	}
	return False, nil
}

// Count the matches of an element, a run (non-overlapping occurrences), a set or a predicate; with no argument, the
// significant elements.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// ```go
// [1, 2, 1, 1].count(1)              // => 3
// [1, 2, 1, 2, 2].count([1, 2])      // => 2
// [1, 0, undefined, "", 2].count()   // => 2 — significant elements
// ```
//
//kavun:member count pure (...x) -> int
func arrayCount(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := arrayReadMatchArgs(vm, "count", args, true)
	if err != nil {
		return Undefined, err
	}
	elems := (*Array)(v.Ptr).Elements

	n := int64(0)
	if m.runs != nil {
		for i := 0; i < len(elems); {
			if k := arrayRunLengthAt(elems, i, m.runs); k > 0 {
				n++
				i += k
			} else {
				i++
			}
		}
		return IntValue(n), nil
	}

	for i, e := range elems {
		hit, err := m.matches(i, e)
		if err != nil {
			return Undefined, err
		}
		if hit {
			n++
		}
	}
	return IntValue(n), nil
}

// Report whether some element matches a value, a set or a predicate; with no argument, whether any element is
// significant.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// A run argument raises **permanently** — "all of a run" has no universal reading:
//
// ```go
// [2, 4].all(func(x) { return x % 2 == 0 })  // => true
// [2, 2].all(2)            // => true
// [1, 2].any(5, 2)         // => true — a set
// ["", 0, "x"].any()       // => true — some element is significant
// [1, 2, 3].any([2, 3])    // Error: invalid_argument_type — any) ... an element or a predicate (no run reading
// ```
//
//kavun:member any pure (...x) -> bool
func arrayAny(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := arrayReadMatchArgs(vm, "any", args, false)
	if err != nil {
		return Undefined, err
	}
	for i, e := range (*Array)(v.Ptr).Elements {
		hit, err := m.matches(i, e)
		if err != nil {
			return Undefined, err
		}
		if hit {
			return True, nil
		}
	}
	return False, nil
}

// Report whether every element matches a value, a set or a predicate; with no argument, whether every element is
// significant; see [`any`](#any).
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
//kavun:member all pure (...x) -> bool
func arrayAll(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	// True on an empty array.
	m, err := arrayReadMatchArgs(vm, "all", args, false)
	if err != nil {
		return Undefined, err
	}
	for i, e := range (*Array)(v.Ptr).Elements {
		hit, err := m.matches(i, e)
		if err != nil {
			return Undefined, err
		}
		if !hit {
			return False, nil
		}
	}
	return True, nil
}

// Answer the first position of a match of an element, a run or a predicate, or `undefined` (the `default` when given)
// on a miss.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// `index` and [`index_last`](#index_last) are the only locators.
//
// Never variadic — the optional trailing argument is always the miss default. A miss answers `undefined` (never
// `-1`). The no-argument form finds the first/last element outside the blank set.
//
// ```go
// [1, 2, 3, 2].index(2)          // => 1
// [1, 2, 3, 2].index_last(2)     // => 3
// [1, 2].index(9)                // => undefined — a miss, never -1
// [1, 2].index(9, -1)            // => -1 — the explicit default
// [0, undefined, "", 7, 0].index()   // => 3 — first significant element
// [1, 2, 3].index(func(x) { return x > 1 })   // => 1
// ```
//
//kavun:member index pure ([x[, default]]) -> int
func arrayIndex(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	return arrayLocate(vm, "index", v, args, false)
}

// Answer the last position of a match, or `undefined` (the `default` when given) on a miss; see [`index`](#index).
//
//kavun:member index_last pure ([x[, default]]) -> int
func arrayIndexLast(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	return arrayLocate(vm, "index_last", v, args, true)
}

// Repeatedly drop the elements at both ends while they belong to the set (the blank set with no argument).
//
// Elements only — a run argument raises (the anchored run form is `remove_prefix`/`remove_suffix`), and there is
// no predicate reading. No arguments trims the [blank set](#the-blank-set).
//
// ```go
// [0, 1, 2, 0, 0].trim(0)            // => [1, 2]
// [0, 9, 1, 9, 0].trim(0, 9)         // => [1]
// [undefined, 0, 1, 0, undefined].trim()   // => [1]
// [1, 2, 3].trim([1, 2])   // Error: invalid_argument_type — trim) ... a set of elements (the anchored run form is remove_prefix/remove_suffix
// ```
//
//kavun:member trim pure (...set) -> array
func arrayTrim(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := arrayTrimmed("trim", v, args, true, true)
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue(out, false), nil
}

// Drop the leading elements that belong to the set (the blank set with no argument); see [`trim`](#trim).
//
//kavun:member trim_start pure (...set) -> array
func arrayTrimStart(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := arrayTrimmed("trim_start", v, args, true, false)
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue(out, false), nil
}

// Drop the trailing elements that belong to the set (the blank set with no argument); see [`trim`](#trim).
//
//kavun:member trim_end pure (...set) -> array
func arrayTrimEnd(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := arrayTrimmed("trim_end", v, args, false, true)
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue(out, false), nil
}

// Remove the element or run — or the longest of a set of them — once, anchored at the front; absent → unchanged.
//
// ```go
// [1, 2, 1, 2, 3].remove_prefix([1, 2])   // => [1, 2, 3] — once, not repeatedly
// [1, 2, 3].remove_suffix([2, 3])         // => [1]
// [1, 2].remove_prefix([9])               // => [1, 2] — no match, unchanged
// ```
//
//kavun:member remove_prefix pure (x, ...more) -> array
func arrayRemovePrefix(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := arrayWithoutAnchored("remove_prefix", v, args, false)
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue(out, false), nil
}

// Remove the element or run — or the longest of a set of them — once, anchored at the back; absent → unchanged;
// see [`remove_prefix`](#remove_prefix).
//
//kavun:member remove_suffix pure (x, ...more) -> array
func arrayRemoveSuffix(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := arrayWithoutAnchored("remove_suffix", v, args, true)
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue(out, false), nil
}

// Report whether the array starts with the element or run, or with any of a set of them.
//
// No predicate ("the first element satisfies `f`" is `index(f) == 0`) and no no-argument form.
//
// ```go
// [1, 2, 3].has_prefix(1)            // => true
// [1, 2, 3].has_prefix([1, 2])       // => true
// [1, 2, 3].has_prefix(9, 1)         // => true — any of the set
// ```
//
//kavun:member has_prefix pure (x, ...more) -> bool
func arrayHasPrefix(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	best, err := arrayAnchoredRun("has_prefix", v, args, false)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(best >= 0), nil
}

// Report whether the array ends with the element or run, or with any of a set of them; see [`has_prefix`](#has_prefix).
//
//kavun:member has_suffix pure (x, ...more) -> bool
func arrayHasSuffix(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	best, err := arrayAnchoredRun("has_suffix", v, args, true)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(best >= 0), nil
}

// Replace every occurrence of `old`, an element or a run, with `new`.
//
// Both positions take an element or a run; never variadic (the second position is the replacement), never a
// predicate.
//
// ```go
// [1, 2, 1].replace(1, 9)            // => [9, 2, 9]
// [1, 2, 3, 1, 2].replace([1, 2], 0) // => [0, 3, 0] — run to element
// [1, 2].replace(1, [7, 8])          // => [7, 8, 2] — element to run
// ```
//
//kavun:member replace pure (old, new) -> array
func arrayReplace(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := arrayReplaced("replace", v, args)
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue(out, false), nil
}

// Pad at the front with the fill element until length `n`.
//
// The fill is always **one element**, whatever its type — an array fill is inserted whole per slot, never spread —
// and defaults to `undefined`. A width at or below the current length is a no-op; a width past `4294967296`
// elements raises rather than exhausting the host.
//
// ```go
// [1, 2].pad_start(5, 0)     // => [0, 0, 0, 1, 2]
// [1, 2].pad_end(4)          // => [1, 2, undefined, undefined]
// [1].pad_end(3, [0, 0])     // => [1, [0, 0], [0, 0]] — the fill is one element
// [1, 2].pad_start(1, 0)     // => [1, 2] — width below length: no-op
// ```
//
//kavun:member pad_start pure (n[, fill]) -> array
func arrayPadStart(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := arrayPadded("pad_start", v, args, true)
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue(out, false), nil
}

// Pad at the back with the fill element until length `n`; see [`pad_start`](#pad_start).
//
//kavun:member pad_end pure (n[, fill]) -> array
func arrayPadEnd(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := arrayPadded("pad_end", v, args, false)
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue(out, false), nil
}

// Answer the callback's result for each element, strictly 1:1.
//
// The callback gets the element, or `(index, element)` when it does not accept one argument ([callbacks](#callbacks)).
//
// A nested result nests; `undefined` stays:
//
// ```go
// [1, 2, 3].map(func(x) { return x * 2 })        // => [2, 4, 6]
// [10, 20].map(func(i, v) { return i + v })      // => [10, 21]
// [1, 2].map(func(x) { return [x] })             // => [[1], [2]] — nesting preserved
// [1, undefined, 2].map(func(x) { return x })    // => [1, undefined, 2]
// ```
//
//kavun:member map pure (fn) -> array
func arrayMap(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	cb, err := readElemCallback(vm, "map", args)
	if err != nil {
		return Undefined, err
	}
	elems := (*Array)(v.Ptr).Elements
	out := make([]Value, len(elems))
	for i, e := range elems {
		out[i], err = cb.Call(i, e)
		if err != nil {
			return Undefined, err
		}
	}
	return NewArrayValue(out, false), nil
}

// Map each element through the callback, then concatenate: an `array` result spreads as a run, `undefined` contributes
// nothing, anything else is one element.
//
// The callback gets the element, or `(index, element)` when it does not accept one argument ([callbacks](#callbacks)).
//
// ```go
// [1, 2].flat_map(func(x) { return [x, x * 10] })   // => [1, 10, 2, 20]
// [2, 3].flat_map(func(x) { return range(0, x).array() })   // => [0, 1, 0, 1, 2]
// [1, 2, 3].flat_map(func(x) { if x == 2 { return undefined }; return x })   // => [1, 3]
// ```
//
//kavun:member flat_map pure (fn) -> array
func arrayFlatMap(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	cb, err := readElemCallback(vm, "flat_map", args)
	if err != nil {
		return Undefined, err
	}
	elems := (*Array)(v.Ptr).Elements
	out := make([]Value, 0, len(elems))
	for i, e := range elems {
		res, err := cb.Call(i, e)
		if err != nil {
			return Undefined, err
		}
		switch res.Type {
		case value.Undefined:
		case value.Array:
			out = append(out, (*Array)(res.Ptr).Elements...)
		default:
			out = append(out, res)
		}
	}
	return NewArrayValue(out, false), nil
}

// Fold the elements left to right into an accumulator that starts at `init`.
//
// The callback gets `(acc, element)`, or `(acc, index, element)` when it does not accept two arguments
// ([callbacks](#callbacks)):
//
// ```go
// [1, 2, 3].reduce(0, func(acc, v) { return acc + v })          // => 6
// [1, 2, 3].reduce(0, func(acc, i, v) { return acc + i * v })   // => 8
// ```
//
//kavun:member reduce pure (init, fn) -> value
func arrayReduce(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	acc, cb, err := readReduceArgs(vm, args)
	if err != nil {
		return Undefined, err
	}
	for i, e := range (*Array)(v.Ptr).Elements {
		acc, err = cb.Call(acc, i, e)
		if err != nil {
			return Undefined, err
		}
	}
	return acc, nil
}

// Call the callback on every element — always a **full pass**, its return value ignored — and return the receiver.
//
// The callback gets the element, or `(index, element)` when it does not accept one argument ([callbacks](#callbacks)).
//
// Early exit belongs to `for`/`break` or a search member.
//
// ```go
// sum = 0
// r = [1, 2, 3].for_each(func(v) { sum += v; return false })
// sum    // => 6 — the false did not stop it
// r      // => [1, 2, 3] — the receiver
// ```
//
//kavun:member for_each pure (fn) -> array
func arrayForEach(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	cb, err := readElemCallback(vm, "for_each", args)
	if err != nil {
		return Undefined, err
	}
	for i, e := range (*Array)(v.Ptr).Elements {
		if _, err := cb.Call(i, e); err != nil {
			return Undefined, err
		}
	}
	return v, nil
}

