// Unwrap nested `array` elements, one level by default.
//
// Only array elements are unwrapped; every other element type stays intact. `flat_map(f)` ≠ `map(f).flatten()` —
// `flatten` unwraps any nested array, at any position.
//
// ```go
// [1, [2, [3]]].flatten()          // => [1, 2, [3]] — one level
// [1, [2, [3]]].flatten(2)         // => [1, 2, 3]
// [range(0, 2), [1]].flatten()     // => [range(0, 2), 1] — only arrays unwrap
// ```
//
//kavun:member flatten pure ([depth]) -> array
func arrayFlatten(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "flatten"
	if len(args) > 1 {
		return Undefined, ErrArgCount
	}
	depth := 1
	if len(args) == 1 {
		d, ok := args[0].AsInt()
		if !ok {
			return Undefined, errs.NewInvalidArgumentTypeError(name, "first", "int", args[0].TypeName())
		}
		if d < 0 {
			depth = -1
		} else {
			depth = int(d)
		}
	}
	o := (*Array)(v.Ptr)
	out := make([]Value, 0, len(o.Elements))
	out = flattenAppend(out, o.Elements, depth)
	arr := make([]Value, len(out))
	copy(arr, out)
	return NewArrayValue(arr, false), nil
}

// Reorder the elements randomly, drawing from a [`rand.generator`](rand_generator.md) — required, because a
// member cannot read the world on its own.
