// The same seeded generator gives the same order on every run; `os.rand_generator()` gives an unpredictable one.
// Fisher–Yates over `g.int(i + 1)`, so the generator's state moves:
//
// ```go
// g := import("rand").generator(7)
// [1, 2, 3, 4, 5].shuffle(g)        // => [3, 5, 4, 1, 2]
// a := [1, 2, 3]
// a.shuffle_in_place(import("rand").generator(3))   // a is [2, 3, 1]
// [1, 2].shuffle(5)                 // Error: invalid_argument_type: (shuffle) argument first expects type rand.generator, got int
// ```
//
//kavun:member shuffle impure (g) -> array
func arrayShuffle(vm VM, v Value, id member.ID, args []Value) (Value, error) {
	out := slices.Clone((*Array)(v.Ptr).Elements)
	if err := shuffleWith(vm, id, args[0], out); err != nil {
		return Undefined, err
	}
	return NewArrayValue(out, false), nil
}

