// Answer the smallest element; an empty array raises unless a default is given.
//
//kavun:member min pure ([default]) -> value
func arrayMin(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	if len(args) > 1 {
		return Undefined, ErrArgCount
	}

	o := (*Array)(v.Ptr)
	if len(o.Elements) == 0 {
		return emptySeqResult("min", args)
	}

	e := o.Elements[0]
	for i := 1; i < len(o.Elements); i++ {
		less, err := o.Elements[i].BinaryOp(tokens.Less, e)
		if err != nil {
			return Undefined, err
		}
		lt, terr := less.IsTrue()
		if terr != nil {
			return Undefined, terr
		}
		if lt {
			e = o.Elements[i]
		}
	}

	return e, nil
}

