// The free `is_view(x)` reports it; see [container semantics](../../container_semantics.md) before using views.
//
// ```go
// a = [1, 2, 3, 4]
// b = a.slice_view(1, 3)
// b[0] = 99
// a              // => [1, 99, 3, 4]
// is_view(b)     // => true
// ```
//
//kavun:member slice_view pure ([start[, end]]) -> array
func arraySliceView(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "slice_view"
	s, e, err := readSliceArgs(name, args)
	if err != nil {
		return Undefined, err
	}
	elems := (*Array)(v.Ptr).Elements
	si, ei, err := resolveSliceBounds(name, s, e, len(elems))
	if err != nil {
		return Undefined, err
	}
	res := NewArrayValue(elems[si:ei], v.Immutable)
	(*Array)(res.Ptr).IsView = true
	return res, nil
}

// Split into arrays of up to `n` elements, each a copy.
//
// `chunk` copies, [`chunk_view`](#chunk_view) shares.
//
// ```go
// [1, 2, 3, 4, 5].chunk(2)       // => [[1, 2], [3, 4], [5]]
// a = [1, 2, 3, 4]
// c = a.chunk_view(2)
// c[0][0] = 9
// a                              // => [9, 2, 3, 4]
// ```
//
//kavun:member chunk pure (n) -> array
func arrayChunk(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	size, err := readChunkSize("chunk", args)
	if err != nil {
		return Undefined, err
	}
	elems := (*Array)(v.Ptr).Elements
	step := len(elems)
	if size < int64(step) {
		step = int(size)
	}
	chunks := make([]Value, 0)
	for start := 0; start < len(elems); start += step {
		chunks = append(chunks, NewArrayValue(slices.Clone(elems[start:min(start+step, len(elems))]), false))
	}
	return NewArrayValue(chunks, false), nil
}

// Split into arrays of up to `n` elements sharing the receiver's storage, each marked as a view; see [`chunk`](#chunk).
//
//kavun:member chunk_view pure (n) -> array
func arrayChunkView(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	size, err := readChunkSize("chunk_view", args)
	if err != nil {
		return Undefined, err
	}
	elems := (*Array)(v.Ptr).Elements
	step := len(elems)
	if size < int64(step) {
		step = int(size)
	}
	chunks := make([]Value, 0)
	for start := 0; start < len(elems); start += step {
		c := NewArrayValue(elems[start:min(start+step, len(elems))], v.Immutable)
		(*Array)(c.Ptr).IsView = true
		chunks = append(chunks, c)
	}
	return NewArrayValue(chunks, false), nil
}

// Join the rendered elements into text, with the optional separator between them.
//
// The collection is the receiver, the separator the optional argument.
