// Concatenate the array with itself `n` times; `a * n` is the operator form.
//
// The count must be a whole non-negative number: `2.0` converts, `1.5` raises — never silent truncation. A result
// past `4294967296` elements raises rather than exhausting the host.
//
// ```go
// [1, 2].repeat(3)       // => [1, 2, 1, 2, 1, 2]
// [1, 2] * 3             // => [1, 2, 1, 2, 1, 2] — the operator form
// [1, 2].repeat(2.0)     // => [1, 2, 1, 2]
// [1, 2].repeat(1.5)     // Error: invalid_value: (repeat) argument first must be a whole number, got 1.5
// ```
//
//kavun:member repeat pure (n) -> array
func arrayRepeat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*Array)(v.Ptr)
	n, err := parseRepeatCount(name, args)
	if err != nil {
		return Undefined, err
	}
	src := o.Elements
	sl := len(src)
	total, err := seq.RepeatTotal(name, n, sl)
	if err != nil {
		return Undefined, err
	}
	out := make([]Value, total)
	// step by the receiver's length, never by the count: an empty receiver has total 0 and must not
	// spin n times copying nothing
	for i := 0; i < total; i += sl {
		copy(out[i:], src)
	}
	return NewArrayValue(out, false), nil
}

// Convert each element to one symbol of a `string`: ints are read as code points, runes and bytes as themselves.
